import Close from './action-bar-close.svelte';
import Group from './action-bar-group.svelte';
import Item from './action-bar-item.svelte';
import Portal from './action-bar-portal.svelte';
import Selection from './action-bar-selection.svelte';
import Separator from './action-bar-separator.svelte';
import Root from './action-bar.svelte';

export {
	type ActionBarChildProps,
	type ActionBarProps,
	type ActionBarRootProps
} from './action-bar.svelte';
export {
	type ActionBarSelectionChildProps,
	type ActionBarSelectionProps
} from './action-bar-selection.svelte';
export { type ActionBarGroupChildProps, type ActionBarGroupProps } from './action-bar-group.svelte';
export {
	type ActionBarItemChildProps,
	type ActionBarItemProps,
	type ActionBarItemSelectEvent
} from './action-bar-item.svelte';
export { type ActionBarCloseChildProps, type ActionBarCloseProps } from './action-bar-close.svelte';
export {
	type ActionBarSeparatorChildProps,
	type ActionBarSeparatorProps
} from './action-bar-separator.svelte';
export { type ActionBarPortalProps } from './action-bar-portal.svelte';

export {
	ACTION_BAR_ENTRY_FOCUS,
	ACTION_BAR_EVENT_OPTIONS,
	ACTION_BAR_ITEM_SELECT,
	ACTION_BAR_ITEM_SELECT_OPTIONS,
	ActionBarRootState,
	actionBarSeparatorVariants,
	getActionBarContext,
	setActionBarContext,
	type ActionBarAlign,
	type ActionBarOrientation,
	type ActionBarRootStateProps,
	type ActionBarSide
} from './action-bar.svelte.js';

// Component-agnostic on purpose: `selection-toolbar` imports these instead of duplicating them
// (FR-016, quickstart §5). Neither shared module imports an `action-bar-*` part.
export {
	DEFAULT_ALIGN_OFFSET,
	DEFAULT_SIDE_OFFSET,
	EscapeDismissState,
	FLOATING_ALIGNMENTS,
	FLOATING_ORIENTATIONS,
	FLOATING_SIDES,
	floatingSurfaceVariants,
	getViewportEdgeStyle,
	type EscapeDismissStateProps,
	type FloatingAlign,
	type FloatingOrientation,
	type FloatingSide,
	type ViewportEdgeStyleOptions
} from './action-bar-floating.svelte.js';

export {
	focusFirst,
	getDirectionAwareKey,
	getFocusIntent,
	getRovingFocusContext,
	ROVING_FOCUS_INTENTS,
	RovingFocusGroupState,
	setRovingFocusContext,
	wrapArray,
	type RovingFocusGroupStateProps,
	type RovingFocusIntent,
	type RovingFocusItemMeta
} from './action-bar-roving-focus.svelte.js';

export {
	Root,
	Selection,
	Separator,
	Group,
	Item,
	Close,
	Portal,
	//
	Root as ActionBar,
	Selection as ActionBarSelection,
	Separator as ActionBarSeparator,
	Group as ActionBarGroup,
	Item as ActionBarItem,
	Close as ActionBarClose,
	Portal as ActionBarPortal
};

import type { Direction } from '$lib/components/ui/direction-provider/index.js';
import { getContext, hasContext, setContext } from 'svelte';
import { tv } from 'tailwind-variants';

import type {
	FloatingAlign,
	FloatingOrientation,
	FloatingSide
} from './action-bar-floating.svelte.js';

/** Upstream `ActionBarProps["side"]`, under the component's own name. */
export type ActionBarSide = FloatingSide;

/** Upstream `ActionBarProps["align"]`, under the component's own name. */
export type ActionBarAlign = FloatingAlign;

/** Upstream `Orientation`, under the component's own name. */
export type ActionBarOrientation = FloatingOrientation;

/** Bubbling, cancelable event an item dispatches on itself. Upstream `ITEM_SELECT` (20). */
export const ACTION_BAR_ITEM_SELECT = 'actionbar.itemSelect';

/** Cancelable event the group dispatches when focus enters it. Upstream `ENTRY_FOCUS` (21). */
export const ACTION_BAR_ENTRY_FOCUS = 'actionbarFocusGroup.onEntryFocus';

/** Upstream `EVENT_OPTIONS` (22) — the entry-focus event does **not** bubble. */
export const ACTION_BAR_EVENT_OPTIONS = { bubbles: false, cancelable: true } as const;

/** Upstream's inline init for the item-select event (476-479), which **does** bubble. */
export const ACTION_BAR_ITEM_SELECT_OPTIONS = { bubbles: true, cancelable: true } as const;

/**
 * Upstream `ActionBarSeparator`'s class list (652-656).
 *
 * Not the shared `$lib/components/ui/separator`: upstream deliberately pairs `role="separator"`
 * with `aria-hidden="true"` — a decorative divider that is still selectable for styling — and its
 * classes depend on the `in-data-[slot=action-bar-selection]:` contextual variant to shrink inside
 * the selection pill. Neither is expressible through the shared component's `bits-ui`-backed ARIA
 * contract (research R-18).
 */
export const actionBarSeparatorVariants = tv({
	base: 'in-data-[slot=action-bar-selection]:ml-0.5 in-data-[slot=action-bar-selection]:h-4 in-data-[slot=action-bar-selection]:w-px bg-border',
	variants: {
		orientation: {
			horizontal: 'h-6 w-px',
			vertical: 'h-px w-full'
		}
	},
	defaultVariants: {
		orientation: 'horizontal'
	}
});

export type ActionBarRootStateProps = {
	readonly getOpen: () => boolean;
	/**
	 * Writes the caller's binding **and** calls `onOpenChange` — the only path that changes `open`.
	 * The write is skipped when the caller's `open` already reads as `open`, so a controlled prop
	 * passed without `bind:` is never shadowed by a redundant local override; `onOpenChange` still
	 * fires on every request (FR-002).
	 */
	readonly setOpen: (open: boolean) => void;
	readonly getDir: () => Direction;
	readonly getOrientation: () => ActionBarOrientation;
	readonly getLoop: () => boolean;
};

/**
 * One instance per `<ActionBar>`, published on context. Upstream `ActionBarContextValue`
 * (70-79, 180-188).
 *
 * The class never assigns to `open` itself: {@link ActionBarRootState.setOpen} is the single write
 * path, and it always notifies `onOpenChange` (FR-002).
 */
export class ActionBarRootState {
	// `$derived` below is lazy at runtime, but svelte-check cannot see that across the constructor
	// assignment — the same annotation `DirectionProviderState` needs.
	#props!: ActionBarRootStateProps;

	readonly open: boolean = $derived(this.#props.getOpen());
	readonly dir: Direction = $derived(this.#props.getDir());
	readonly orientation: ActionBarOrientation = $derived(this.#props.getOrientation());
	readonly loop: boolean = $derived(this.#props.getLoop());

	constructor(props: ActionBarRootStateProps) {
		this.#props = props;
	}

	setOpen(next: boolean): void {
		this.#props.setOpen(next);
	}
}

const ACTION_BAR_CONTEXT_KEY = Symbol('action-bar');

export function setActionBarContext(state: ActionBarRootState): ActionBarRootState {
	return setContext(ACTION_BAR_CONTEXT_KEY, state);
}

/** Read the root's state, throwing when there is no `<ActionBar>` ancestor (FR-014). */
export function getActionBarContext(consumerName: string): ActionBarRootState {
	if (!hasContext(ACTION_BAR_CONTEXT_KEY)) {
		throw new Error(`\`${consumerName}\` must be used within \`<ActionBar>\`.`);
	}
	return getContext<ActionBarRootState>(ACTION_BAR_CONTEXT_KEY);
}

import { tv } from 'tailwind-variants';

/**
 * Component-agnostic mechanics of a floating surface docked to a viewport edge: the inline style
 * that pins it, the enter/exit transition recipe, and the `Escape` dismisser.
 *
 * Nothing here imports an `action-bar-*` part — the dependency arrow points parts → this module,
 * never back — so the next port (`selection-toolbar`) composes these instead of duplicating them
 * (FR-016). The names are deliberately `Floating*`, not `ActionBar*`.
 */

/** Every value `side` accepts. Upstream `ActionBarProps["side"]` (action-bar.tsx:118). */
export const FLOATING_SIDES = ['top', 'bottom'] as const;
export type FloatingSide = (typeof FLOATING_SIDES)[number];

/** Every value `align` accepts. Upstream `ActionBarProps["align"]` (116). */
export const FLOATING_ALIGNMENTS = ['start', 'center', 'end'] as const;
export type FloatingAlign = (typeof FLOATING_ALIGNMENTS)[number];

/** Every value `orientation` accepts. Upstream `Orientation` (25). */
export const FLOATING_ORIENTATIONS = ['horizontal', 'vertical'] as const;
export type FloatingOrientation = (typeof FLOATING_ORIENTATIONS)[number];

/** Distance from the docked viewport edge, in px. Upstream default (134). */
export const DEFAULT_SIDE_OFFSET = 16;

/** Distance from the aligned viewport edge, in px. Upstream default (132). */
export const DEFAULT_ALIGN_OFFSET = 0;

export type ViewportEdgeStyleOptions = {
	readonly side: FloatingSide;
	readonly sideOffset: number;
	readonly align: FloatingAlign;
	readonly alignOffset: number;
};

/**
 * The declarations that pin a `position: fixed` surface to a viewport edge, as a `style` string.
 *
 * A verbatim translation of upstream's inline style object (action-bar.tsx:220-229). The anchor is
 * the viewport rather than a trigger element, which is why no `bits-ui` positioner fits: every one
 * of them measures a placement against an anchor element (plan.md justification 1).
 *
 * `left`/`right` are physical on purpose — upstream does not use logical `inset-inline-*`, so
 * `align="start"` stays visually left-anchored under `dir="rtl"`; only keyboard navigation inverts
 * (research R-04).
 */
export function getViewportEdgeStyle({
	side,
	sideOffset,
	align,
	alignOffset
}: ViewportEdgeStyleOptions): string {
	const edge = `${side}: ${sideOffset}px;`;
	switch (align) {
		case 'center':
			return `${edge} left: 50%; translate: -50% 0;`;
		case 'start':
			return `${edge} left: ${alignOffset}px;`;
		case 'end':
			return `${edge} right: ${alignOffset}px;`;
	}
}

/**
 * Chrome and transition of a floating surface. Upstream's class list (action-bar.tsx:210-219),
 * with the mirrored `data-[state=closed]` half added so a consumer that keeps the surface mounted
 * while closing gets a real exit animation, and with `text-card-foreground text-sm` pairing the
 * `bg-card` fill — the surface portals to `document.body`, so like the kit's other floating
 * surfaces (`popover-content.svelte`) it must set its own text colour and size rather than
 * inherit the page's.
 *
 * `ActionBar` itself never renders in the closed state — FR-001 requires a synchronous unmount —
 * so on this component the exit half is inert; it exists for the reuse contract (research R-17).
 *
 * `z-50` is deliberate. Constitution VIII forbids manual `z-index` on overlays whose primitive owns
 * stacking (Dialog/Sheet/Popover/Tooltip); this is a bespoke self-portalled surface with no such
 * owner, exactly like `banner-queue.svelte` and upstream itself (plan.md "Styling note").
 */
export const floatingSurfaceVariants = tv({
	base: [
		'fixed z-50 rounded-lg border bg-card text-sm text-card-foreground shadow-lg outline-none',
		'animate-in fade-in-0 zoom-in-95 duration-250 [animation-timing-function:cubic-bezier(0.16,1,0.3,1)]',
		'data-[side=bottom]:slide-in-from-bottom-4 data-[side=top]:slide-in-from-top-4',
		'data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95',
		'data-[state=closed]:data-[side=bottom]:slide-out-to-bottom-4 data-[state=closed]:data-[side=top]:slide-out-to-top-4',
		'motion-reduce:animate-none motion-reduce:transition-none'
	],
	variants: {
		orientation: {
			horizontal: 'flex flex-row items-center gap-2 px-2 py-1.5',
			vertical: 'flex flex-col items-start gap-2 px-1.5 py-2'
		}
	},
	defaultVariants: {
		orientation: 'horizontal'
	}
});

export type EscapeDismissStateProps = {
	/** The listener is attached only while this returns `true` — i.e. while the surface is open. */
	readonly getEnabled: () => boolean;
	/** `ref?.ownerDocument ?? document`, so the listener is correct inside an iframe. */
	readonly getOwnerDocument: () => Document;
	/** Called first on every `Escape`. `preventDefault()` cancels the dismissal. */
	readonly onEscapeKeyDown?: (event: KeyboardEvent) => void;
	/** Called unless the event was default-prevented. */
	readonly onDismiss: () => void;
};

/**
 * Dismisses a non-modal floating surface on `Escape`. Upstream's effect (action-bar.tsx:162-178).
 *
 * `bits-ui` exports no standalone escape layer, and the widgets that own the behaviour bundle it
 * with modality, focus trapping, scroll locking and outside-click dismissal — none of which a
 * non-modal action bar has (plan.md justification 2). Must be constructed during component
 * initialisation, because it owns an `$effect`.
 */
export class EscapeDismissState {
	// `$effect` below is created in the constructor, but svelte-check's static analysis cannot see
	// the assignment happening first — the same annotation `DirectionProviderState` needs.
	#props!: EscapeDismissStateProps;

	constructor(props: EscapeDismissStateProps) {
		this.#props = props;

		$effect(() => {
			if (!this.#props.getEnabled()) return;

			const ownerDocument = this.#props.getOwnerDocument();

			const onKeyDown = (event: KeyboardEvent) => {
				if (event.key !== 'Escape') return;
				this.#props.onEscapeKeyDown?.(event);
				if (event.defaultPrevented) return;
				this.#props.onDismiss();
			};

			ownerDocument.addEventListener('keydown', onKeyDown);
			return () => ownerDocument.removeEventListener('keydown', onKeyDown);
		});
	}
}

import type { Direction } from '$lib/components/ui/direction-provider/index.js';
import {
	DomOrderedCollection,
	type DomOrderedEntry
} from '$lib/components/ui/speed-dial/speed-dial-collection.svelte.js';
import { getContext, hasContext, setContext } from 'svelte';

import type { FloatingOrientation } from './action-bar-floating.svelte.js';

/**
 * Component-agnostic implementation of the WAI-ARIA Toolbar roving-tabindex pattern: one tab stop
 * for a whole group of controls, arrow keys moving between them, `Home`/`End` jumping to the ends,
 * `loop` wrapping, disabled entries skipped and the horizontal arrows inverted under `dir="rtl"`.
 *
 * Nothing here imports an `action-bar-*` part, so `selection-toolbar` composes it as-is (FR-016).
 * The item registry itself is *not* bespoke: it is `speed-dial`'s exported
 * {@link DomOrderedCollection}, which already implements upstream's `compareDocumentPosition`
 * ordering and `isConnected` filter (research R-06).
 */

/** Where a navigation key wants focus to land. Upstream's `focusIntent` union (action-bar.tsx:518). */
export const ROVING_FOCUS_INTENTS = ['first', 'last', 'prev', 'next'] as const;
export type RovingFocusIntent = (typeof ROVING_FOCUS_INTENTS)[number];

/**
 * Metadata every item registers with. `disabled` is a **getter**, read at event time, so an item
 * that becomes disabled after registration is skipped without re-registering.
 */
export type RovingFocusItemMeta = {
	readonly getDisabled: () => boolean;
};

/** `{ bubbles: false, cancelable: true }` — upstream `EVENT_OPTIONS` (action-bar.tsx:22). */
const DEFAULT_ENTRY_FOCUS_OPTIONS: CustomEventInit = { bubbles: false, cancelable: true };

/**
 * Focus the first candidate that actually takes focus. Upstream `focusFirst` (35-47).
 *
 * Two behaviours make this more than `candidates[0]?.focus()`: it returns without moving anything
 * when the first candidate is *already* the active element (so `Home` on the first item is a no-op
 * rather than a jump), and it walks on when a candidate refuses focus (detached or disabled).
 */
export function focusFirst(candidates: readonly HTMLElement[], preventScroll = false): void {
	const previouslyFocused = document.activeElement;
	for (const candidate of candidates) {
		if (candidate === previouslyFocused) return;
		candidate.focus({ preventScroll });
		if (document.activeElement !== previouslyFocused) return;
	}
}

/** Rotate `array` so that `startIndex` comes first. Upstream `wrapArray` (49-53). */
export function wrapArray<T>(array: readonly T[], startIndex: number): T[] {
	return array.map((_, index) => array[(startIndex + index) % array.length] as T);
}

/** Swap the two horizontal arrows under `rtl`. Upstream `getDirectionAwareKey` (55-62). */
export function getDirectionAwareKey(key: string, dir?: Direction): string {
	if (dir !== 'rtl') return key;
	if (key === 'ArrowLeft') return 'ArrowRight';
	if (key === 'ArrowRight') return 'ArrowLeft';
	return key;
}

/**
 * Resolve a key into a navigation intent for the given axis and reading direction, or `undefined`
 * when the toolbar pattern does not own the key. Upstream's inline branch (action-bar.tsx:517-530),
 * extracted so it is unit-testable and reusable.
 */
export function getFocusIntent(
	key: string,
	orientation: FloatingOrientation,
	dir?: Direction
): RovingFocusIntent | undefined {
	const resolved = getDirectionAwareKey(key, dir);
	if (resolved === 'Home') return 'first';
	if (resolved === 'End') return 'last';
	if (orientation === 'horizontal') {
		if (resolved === 'ArrowLeft') return 'prev';
		if (resolved === 'ArrowRight') return 'next';
		return undefined;
	}
	if (resolved === 'ArrowUp') return 'prev';
	if (resolved === 'ArrowDown') return 'next';
	return undefined;
}

export type RovingFocusGroupStateProps = {
	readonly getDir: () => Direction;
	readonly getOrientation: () => FloatingOrientation;
	readonly getLoop: () => boolean;
	/** Name of the cancelable event dispatched on the group when focus enters it from the keyboard. */
	readonly entryFocusEventName: string;
	/** @default { bubbles: false, cancelable: true } */
	readonly entryFocusEventOptions?: CustomEventInit;
};

/**
 * One instance per roving-focus group, published on context.
 *
 * Replaces upstream's `FocusContext` plus the `ActionBarGroup` state it carries (89-110, 265-391).
 * `bits-ui`'s `Toolbar` cannot stand in: it scopes roving focus to the whole bar, which would rob
 * the close button of its own tab stop, and its `Group` is a toggle group rather than a
 * `role="group"` focus sub-scope (plan.md justification 3).
 */
export class RovingFocusGroupState {
	// `$derived` below is lazy at runtime, but svelte-check cannot see that across the constructor
	// assignment — the `DirectionProviderState` annotation, for the same reason.
	#props!: RovingFocusGroupStateProps;

	/** Document-ordered, `isConnected`-filtered registry of the group's items. */
	readonly items = new DomOrderedCollection<RovingFocusItemMeta>();

	/** Identity of the item that currently owns the group's single tab stop. */
	tabStopId = $state<string | null>(null);

	/** Set by an item's `Shift+Tab`, cleared when focus leaves the group. */
	isTabbingBackOut = $state(false);

	/** Upstream `isClickFocusRef` (272): read once inside a handler, never rendered — so not `$state`. */
	#isClickFocus = false;

	/**
	 * Enabled, attached items. Replaces upstream's manual `focusableItemCount` counter, which is a
	 * React workaround for not having derived state and double-counts when `disabled` toggles
	 * (research R-07).
	 */
	readonly focusableCount: number = $derived(
		this.items.ordered.filter((entry) => !entry.meta.getDisabled()).length
	);

	/** Upstream's group `tabIndex` expression (402). */
	readonly tabIndex: number = $derived(this.isTabbingBackOut || this.focusableCount === 0 ? -1 : 0);

	constructor(props: RovingFocusGroupStateProps) {
		this.#props = props;
	}

	register(id: string, element: HTMLElement, meta: RovingFocusItemMeta): void {
		this.items.register(id, element, meta);
	}

	unregister(id: string): void {
		this.items.unregister(id);
	}

	isTabStop(id: string): boolean {
		return this.tabStopId === id;
	}

	/** Upstream `onItemFocus` (276-278). */
	onItemFocus(id: string): void {
		this.tabStopId = id;
	}

	/** Upstream `onItemShiftTab` (280-282). */
	onItemShiftTab(): void {
		this.isTabbingBackOut = true;
	}

	/** Upstream `onMouseDown` (360-368). */
	onGroupMouseDown(): void {
		this.#isClickFocus = true;
	}

	/** Upstream `onBlur` (318-326) — React's `onBlur` is the bubbling `focusout` (research R-08). */
	onGroupFocusOut(): void {
		this.isTabbingBackOut = false;
	}

	/**
	 * Upstream `onFocus` (328-358). React's `onFocus` is the bubbling `focusin`, which is what makes
	 * the `target === currentTarget` guard meaningful: only focus landing on the group itself is an
	 * entry, focus landing on an item is not.
	 */
	onGroupFocusIn(event: FocusEvent): void {
		const isKeyboardFocus = !this.#isClickFocus;

		if (event.target === event.currentTarget && isKeyboardFocus && !this.isTabbingBackOut) {
			const entryFocusEvent = new CustomEvent(
				this.#props.entryFocusEventName,
				this.#props.entryFocusEventOptions ?? DEFAULT_ENTRY_FOCUS_OPTIONS
			);
			(event.currentTarget as HTMLElement).dispatchEvent(entryFocusEvent);

			if (!entryFocusEvent.defaultPrevented) {
				const enabled = this.#enabledEntries();
				const current = enabled.find((entry) => entry.id === this.tabStopId);
				const candidates = (current ? [current, ...enabled] : enabled).map(
					(entry) => entry.element
				);
				focusFirst(candidates, false);
			}
		}

		this.#isClickFocus = false;
	}

	/**
	 * Move focus according to `intent`, starting from `current`. Upstream's candidate arithmetic
	 * (537-552) verbatim: the reverse-then-wrap trick is what lets one code path serve
	 * prev/next/first/last, and paraphrasing it is how off-by-one wrap bugs get introduced (R-10).
	 */
	navigate(intent: RovingFocusIntent, current: HTMLElement): void {
		let candidates = this.#enabledEntries().map((entry) => entry.element);

		if (intent === 'last') {
			candidates = [...candidates].reverse();
		} else if (intent === 'prev' || intent === 'next') {
			if (intent === 'prev') candidates = [...candidates].reverse();
			const currentIndex = candidates.indexOf(current);
			candidates = this.#props.getLoop()
				? wrapArray(candidates, currentIndex + 1)
				: candidates.slice(currentIndex + 1);
		}

		// Deferred exactly as upstream (552), so the focus move lands after the keydown's own
		// default handling rather than inside it.
		queueMicrotask(() => focusFirst(candidates));
	}

	/** The key of the item whose keydown produced `intent`, resolved through the reading direction. */
	focusIntentFor(key: string): RovingFocusIntent | undefined {
		return getFocusIntent(key, this.#props.getOrientation(), this.#props.getDir());
	}

	#enabledEntries(): DomOrderedEntry<RovingFocusItemMeta>[] {
		return this.items.ordered.filter((entry) => !entry.meta.getDisabled());
	}
}

const ROVING_FOCUS_CONTEXT_KEY = Symbol('roving-focus');

export function setRovingFocusContext(state: RovingFocusGroupState): RovingFocusGroupState {
	return setContext(ROVING_FOCUS_CONTEXT_KEY, state);
}

/**
 * Read the enclosing group's state, throwing when there is none. Upstream `useFocusContext`
 * (102-110) names its internal `FocusProvider`; the message here names the Svelte ancestor a
 * consumer can actually write (research R-14).
 */
export function getRovingFocusContext(
	consumerName: string,
	providerName = '<ActionBar.Group>'
): RovingFocusGroupState {
	if (!hasContext(ROVING_FOCUS_CONTEXT_KEY)) {
		throw new Error(`\`${consumerName}\` must be used within \`${providerName}\`.`);
	}
	return getContext<RovingFocusGroupState>(ROVING_FOCUS_CONTEXT_KEY);
}
